import {mountMeshes} from './mount-meshes.js';
import {bounds,rotateBed} from './mesh.js';
import {affine,rx,rz,rad,scenePoint,sceneBounds,localPoint} from './scene.js';
import {solid} from './solid.js';
export function appendMount(m){if(!m.p.mountMode)return;
 const p=m.p,turn=q=>rz(q,rad(-p.azimuth));
 for(const name of ['base','yoke','cradle']){const mesh=mountMeshes[name];let choice;for(let yaw=0;yaw<180;yaw+=15){const output=rotateBed(mesh,yaw),dim=bounds(output).size;if(dim[0]<=p.bedX-2*p.margin&&dim[1]<=p.bedY-2*p.margin&&dim[2]<=p.bedZ-2){choice={output,dim,yaw};break;}}if(!choice)throw Error('Mount '+name+' exceeds the print volume.');const {output,dim,yaw}=choice;
 const part={id:'mount-'+name,name:'Mount · '+name,mesh,print:output,output,dim,qty:1,kind:'mount',row:-1,bedRotation:yaw,angle:0,supportMeshes:[],spec:{source_sha256:mesh.source_sha256}};m.parts.push(part);
 const fn=name==='base'?q=>rx([q[0],q[1],q[2]-14],-Math.PI):name==='yoke'?q=>turn([q[0],q[1],q[2]+14]):q=>{let v=rx([q[0],q[1],q[2]-75],Math.PI/2);v=rx(v,rad(p.elevation));v[2]+=94;return turn(v);};
 m.instances.push({part,a:0,matrix:affine(fn)});
 }
 const mounts=m.instances.filter(i=>i.part.kind==='mount').map(i=>({id:i.part.id,s:solid(i.part.mesh).transform(q=>scenePoint(m,i,q))}));
 let maxOverlap=0;
 for(const i of m.instances.filter(i=>i.part.kind!=='mount')){const s=solid(i.part.mesh).transform(q=>scenePoint(m,i,q));for(const t of mounts){const overlap=s.intersect(t.s).raw.volume();maxOverlap=Math.max(maxOverlap,overlap);if(overlap>.1)throw Error(`${i.part.name} interferes with ${t.id} at this aiming pose. Change elevation or dish settings.`);}}
 const b=sceneBounds(m),range=[p.seamJoint?-7.5:-10,100],lo=rad(range[0]),hi=rad(range[1]);let sweepMin=0;
 for(const i of m.instances.filter(i=>i.part.kind!=='mount'))for(const q of i.part.mesh.v){const v=rx(localPoint(i,q),-Math.PI/2);v[1]+=75+16-45**2/(4*m.focal);let critical=Math.atan2(v[1],v[2])+Math.PI;while(critical>Math.PI)critical-=2*Math.PI;const angles=[lo,hi,...(critical>=lo&&critical<=hi?[critical]:[])];for(const a of angles)sweepMin=Math.min(sweepMin,94+v[1]*Math.sin(a)+v[2]*Math.cos(a));}
 m.mount={mode:'simple-alt-az',azimuth:p.azimuth,elevation:p.elevation,standClearance:Math.max(0,-b.min[2]),sweepStandClearance:-sweepMin,checkedPose:true,maxOverlap,source:'cad/simple-mount.scad',plateThickness:12,elevationRange:[p.seamJoint?-7.5:-10,100]};
}
export function mountHardware(m){if(!m.p.mountMode)return[];return[{item:'azimuth clamp screw',spec:'M8 × 25 socket head',quantity:1,note:'Nut captured under base; washer and nut listed separately.'},{item:'elevation clamp bolt',spec:'M8 × 40 hex head',quantity:1,note:'Fender washer and wing nut listed separately.'},{item:'azimuth washer',spec:'M8 flat washer',quantity:1,note:'Under socket head.'},{item:'azimuth nut',spec:'M8 hex nut',quantity:1,note:'Captured under base.'},{item:'elevation washer',spec:'M8 fender washer, 24–30 mm OD',quantity:1,note:'Under wing nut.'},{item:'elevation nut',spec:'M8 wing nut',quantity:1,note:'Hand-operated clamp.'},{item:'stand fixing screw',spec:'M5 flat-head / length from stand thickness',quantity:4,note:'Heads must sit below the azimuth bearing face.'}];}
export function mountGuide(m){if(!m.mount)return'';return `Three printed mount parts: base, yoke and cradle. Keep the exported print orientations. Mount hub attachment uses the separately listed external mount hardware; do not buy it twice. ${m.p.mountThrough?'Install the hub with through bolts, washers and nuts in its front seats.':'Use M4 × 18 with one 1 mm washer through the 12 mm cradle: nominal 5 mm insert entry. Verify the actual stack and never bottom out.'} Seat the M8 azimuth nut under the base before fixing the base to the stand with four M5 flat-head screws. Place the yoke on the base and fit M8 × 25 plus washer. Seat the M8 × 40 hex head inside the cradle cheek, pass through the upright, then fit the fender washer and wing nut. Hold the dish while loosening either axis. Aim by hand; these are friction clamps, not geared drives.\n\nSelected pose: azimuth ${m.p.azimuth}°, elevation ${m.p.elevation}°. Geometric clearance below the base is ${m.mount.standClearance.toFixed(1)} mm at this pose. The geometric requirement across the displayed elevation range is ${m.mount.sweepStandClearance.toFixed(1)} mm below the base; add a practical margin for the stand, cable and handling. Changing elevation changes this requirement. The generator checks printed-part interference at the selected pose, not the full movement path, stand, hardware or cable envelope. Plan the sweep before moving. Azimuth hex-key access is limited: set elevation approximately 0–30° to adjust it. The 30 mm hub opening and 34 mm cradle port remain accessible; route and strain-relieve cables before aiming.\n\nASA or a qualified reinforced ASA can be considered for rigid mount parts using the supplier profile, 5–6 walls and locally solid clamp/bolt zones. This is separate from the flexible clip material choice. Test clamp slip and creep under the actual mass and temperature. No load or wind rating is established. Do not compensate for slip by indefinitely increasing torque; inspect and revise the clamp or add a suitable metal load path.`;}
